INSERT INTO public.game_format_prompts(format,title,prompt,depth,icon) SELECT 'wheel', t, p, 'light', '✦' FROM unnest(ARRAY['Passport pose|Strike a pose for a pretend passport photo; everyone guesses your destination.','Window-seat view|Sketch what you wish you could see from the window in 20 seconds.','Two-sound journey|Make two sound effects for a pretend journey; let the squad guess.','Snack mascot|Act out a mascot for your favorite snack; the squad names it.','One-word postcard|Describe your destination with one word and invite a counterproposal.','Silent itinerary|Mime one activity you would enjoy; the squad guesses.','Tiny weather report|Give a ten-second weather report for an imaginary place.','Color compass|Find a color near you that reminds you of this trip and explain why.','Pretend souvenir|Mime a fictional souvenir and have the squad guess its use.','Suitcase charades|Mime packing something ordinary without using words.','Reverse tour guide|Pitch the least exciting thing in the room as a landmark.','Three-word trailer|Give this squad trip a three-word movie trailer title.','Shape search|Point out a shape nearby and let the squad invent its name.','Airplane announcement|Announce tonight’s game as if it were a flight, in ten seconds.','Destination doodle|Draw a symbol for the destination in 20 seconds; everyone guesses.','Favorite flavor|Describe a favorite flavor without naming any food.','Mystery sound|Make a sound with a nearby object; let the group guess what it was.','Invisible dance|Mime a dance move sitting down and have the squad copy it.','Tiny poem|Make a two-line poem about a color you see nearby.','Guess my hobby|Act out a hobby for ten seconds without speaking.','Micro museum|Present an ordinary object as a precious museum exhibit.','Emoji packing list|Describe three pretend packing essentials using only emojis.','Silent celebration|Act out winning a game without making any sound.','Squad headline|Invent a friendly news headline about tonight’s game.','Snack soundtrack|Hum a tune that would accompany your favorite snack.','Travel hat|Mime trying on three imaginary hats; the squad chooses one.','Postcard voice|Say one sentence of a postcard from an imaginary destination.','Opposite day|Describe your ideal day using only opposites; group translates.','Spot the color|Pick a color in the room; others guess which object you chose.','Five-second mascot|Draw a mascot for tonight’s squad in five seconds.']) AS x(v) CROSS JOIN LATERAL (SELECT split_part(v,'|',1) t,split_part(v,'|',2) p) q;
INSERT INTO public.game_format_prompts(format,title,prompt,depth,icon) SELECT 'vote', t, p, 'light', '✦' FROM unnest(ARRAY['Best quick sketch|Whose quick sketch made the group smile?','Best sound effect|Who brought the best sound effect tonight?','Best tiny pitch|Whose mini pitch was the most convincing?','Kindest teammate|Who helped the most people join in?','Most original answer|Who gave the most unexpected answer?','Best make-believe guide|Who made an ordinary object feel special?','Best mime|Whose silent performance told the clearest story?','Best squad headline|Who invented the most memorable headline?','Best tiny poem|Whose poem deserves a second reading?','Best group cheer|Who sparked the loudest group cheer?','Best little detail|Who noticed a delightful detail everyone missed?','Best game recovery|Who bounced back with the biggest laugh?','Best question|Who asked the most interesting question?','Best destination pitch|Who made the destination sound irresistible?','Best pretend souvenir|Who invented the coolest imaginary souvenir?','Best food description|Who painted the tastiest picture in words?','Best invented mascot|Whose mascot belongs on a team shirt?','Best travel story|Whose short story had the best ending?','Best friendly challenge|Who kept a challenge playful and fair?','Best plot twist|Who surprised the squad with a creative twist?','Best imaginary view|Who described the most vivid view?','Best color story|Who gave a color the best backstory?','Best team name|Who came up with the funniest team name?','Best silent clue|Whose mime was easiest to guess?','Best mini celebration|Who gave the most joyful tiny celebration?','Best one-liner|Who landed the cleverest clean one-liner?','Best group moment|Who made tonight feel like a shared adventure?','Best storytelling voice|Who delivered the most entertaining story?','Best improvised prop|Who used a nearby object most creatively?','Best closing thought|Who wrapped up tonight with the warmest thought?']) AS x(v) CROSS JOIN LATERAL (SELECT split_part(v,'|',1) t,split_part(v,'|',2) p) q;
DO $body$ DECLARE source text; BEGIN SELECT pg_get_functiondef('trip_private.night_format_action(uuid,integer,text,text)'::regprocedure) INTO source; source:=replace(source, 'ORDER BY md5(p_trip::text||p_week::text||id::text) LIMIT 1', 'ORDER BY EXISTS (SELECT 1 FROM public.game_night_moments m WHERE m.trip_id=p_trip AND m.prompt_id=game_format_prompts.id), md5(p_trip::text||p_week::text||id::text) LIMIT 1'); source:=replace(source, 'ORDER BY md5(p_trip::text||p_week::text||v_count::text||id::text) LIMIT 1', 'ORDER BY EXISTS (SELECT 1 FROM public.game_night_moments m WHERE m.trip_id=p_trip AND m.prompt_id=game_format_prompts.id), md5(p_trip::text||p_week::text||v_count::text||id::text) LIMIT 1'); source:=replace(source, 'SELECT x INTO v_theme FROM unnest(ARRAY[', 'SELECT x INTO v_theme FROM unnest(ARRAY['); source:=replace(source, '''Show your favorite travel keepsake'']) AS x ORDER BY random() LIMIT 1', '''Show your favorite travel keepsake'',''Share a favorite color'',''Bring an object with a story'',''Wear a pattern you love'',''Show a doodle you made'',''Share your favorite snack wrapper'',''Bring a postcard or drawing'',''Wear your comfiest socks'',''Show a favorite book cover'',''Bring an object in the trip colors'',''Share a made-up team cheer'',''Bring your favorite mug'',''Show an imaginary souvenir sketch'',''Wear your brightest accessory'',''Bring an everyday object with a funny name'',''Draw a mascot for the squad'',''Show a photo you took and are happy to share'',''Bring an item that makes you smile'',''Wear a color inspired by the destination'',''Share a three-word story'',''Bring a drawing of a view you love'']) AS x WHERE NOT EXISTS (SELECT 1 FROM public.game_night_moments m WHERE m.trip_id=p_trip AND m.stage=''final'' AND m.theme=x) ORDER BY random() LIMIT 1'); IF source NOT LIKE '%Share a three-word story%' THEN RAISE EXCEPTION 'Final theme patch did not apply'; END IF; source:=replace(source, 'INSERT INTO public.game_night_moments(trip_id,week_number,stage,actor_id,theme)', 'IF v_theme IS NULL THEN v_theme := ''Bring an object with a story''; END IF; INSERT INTO public.game_night_moments(trip_id,week_number,stage,actor_id,theme)'); EXECUTE source; END $body$;
DO $body$ DECLARE source text; BEGIN SELECT pg_get_functiondef('trip_private.night_flow_action(uuid,integer,text)'::regprocedure) INTO source; source:=replace(source, 'ORDER BY random() LIMIT 1;', 'ORDER BY random() LIMIT 1;'); END $body$;